                    }
                }

            def sub_agent_config(self, name: str):
                return self.agentic_nodes.get(name, {})

            def active_model(self):
                return DummyModelConfig()

        return DBFuncTool(mock_connector, agent_config=DummyAgentConfig(), sub_agent_name="sales")

