def stack(tmp_path):
    k = Kernel.open(tmp_path / "kernel.db")
    sup = k.make_supervisor()
    yield {"kernel": k, "sup": sup}
    for h in sup.list():
        try:
            sup.stop(h.pid)
        except Exception:
            pass
    k.close()

