def stores(tmp_path):
    ks  = KernelStore.open(tmp_path / "kernel.db")
    led = LedgerStore(ks.connection, write_lock=ks.write_lock)
    sup = RunnerSupervisor(ks, ledger_store=led)
    yield {"ks": ks, "led": led, "sup": sup}
    # Clean up any leaked subprocesses.
    for h in sup.list():
        try:
            sup.stop(h.pid)
        except Exception:
            pass
    ks.close()

