def codebase(tmp_path: Path) -> Path:
    """A small multi-language tree (no cocoindex project marker)."""
    (tmp_path / "a.py").write_text(
        "import os


def foo(a, b):
    return a + b


def bar(x):
    return foo(x, 1)
"
    )
    (tmp_path / "sub").mkdir()
    (tmp_path / "sub" / "b.py").write_text("def baz(y):
    return y * 2
")
    (tmp_path / "c.rs").write_text('fn main() {
    println!("hi");
}
')
    # A .txt file that contains python-looking text but is not code.
    (tmp_path / "notes.txt").write_text("def foo(not real code):
")
    return tmp_path

