def cleanup_mas() -> Generator[Callable[[str], None], None, None]:
    """Register Multi-Agent Supervisors for cleanup after test."""
    from databricks_mcp_server.tools.agent_bricks import manage_mas

    mas_to_cleanup = []

    def register(tile_id: str):
