def class_source():
    return textwrap.dedent(
        '''
        """Geometry helpers."""
        from math import pi


        class Shape:
            """Base shape."""

            kind = "shape"

            def __init__(self, name: str) -> None:
                self.name = name

            def describe(self) -> str:
                return f"shape {self.name}"


        class Circle(Shape, metaclass=type):
            """A circle."""

            def __init__(self, r: float) -> None:
                super().__init__("circle")
                self.r = r

            @staticmethod
            def pi_value() -> float:
                return pi

            @classmethod
            def unit(cls) -> "Circle":
                return cls(1.0)

            def area(self) -> float:
                return pi * self.r * self.r
        '''
    ).lstrip()

def oversized_function_source():
    """A function long enough to trigger the secondary line-based split."""
    body_lines = "
".join(f"    x_{i} = {i}" for i in range(200))
    return f"def giant():
{body_lines}
    return x_0
"

def multi_method_class_source(self):
        return textwrap.dedent(
            '''
            class Greeter:
                """A friendly greeter."""

                kind = "greeter"

                def __init__(self, name: str) -> None:
                    self.name = name

                def hello(self) -> str:
                    return f"hello {self.name}"

                def bye(self) -> str:
                    return f"bye {self.name}"

                def shout(self) -> str:
                    return f"HELLO {self.name.upper()}"

                def whisper(self) -> str:
                    return f"hello {self.name}..."
            '''
        ).lstrip()

def rich_module_source(self):
        return textwrap.dedent(
            '''
            """Utility helpers for the pipeline."""
            import os
            import sys
            from pathlib import Path

            MAX_RETRIES = 3
            DEFAULT_TIMEOUT = 30.0
            LOG_PREFIX = "app"


            def process(data):
                """Process data."""
                result = data.strip()
                return result


            def validate(value):
                """Validate a value."""
                if value is None:
                    raise ValueError("value cannot be None")
                return True


            class Manager:
                """Resource manager."""

                def __init__(self):
                    self.items = []

                def add(self, item):
                    self.items.append(item)

                def remove(self, item):
                    self.items.remove(item)


            if __name__ == "__main__":
                mgr = Manager()
                mgr.add(process("test"))
            '''
