    monkeypatch.setattr(fw, "ALLOWED_ROOTS", {tree.resolve()})
    monkeypatch.setattr(fw, "ROOT_DIR", tree)
    def call(**kwargs):
        return mod.GlobFiles().run(SimpleNamespace(), **kwargs)
    return call

