def store():
    """Per-test temporary GlossaryStore on an isolated SQLite file."""
    db = os.path.join(
        tempfile.gettempdir(),
        f"glossary_ner_endpoint_{os.getpid()}_{id(object())}.db",
    )
    if os.path.exists(db):
        os.remove(db)
    s = GlossaryStore(db_path=db)
    try:
        yield s
    finally:
        s.close_all()
        try:
            os.remove(db)
        except OSError:
            pass

