def temp_db(self):
        """Create a temporary database for flight recorder."""
        fd, path = tempfile.mkstemp(suffix=".db")
        os.close(fd)
        yield path
        try:
            os.unlink(path)
        except PermissionError:
            pass  # File may still be in use on Windows

