def provider():
    """Yield a real DockerSandboxProvider and destroy all sessions on teardown."""
    from agent_sandbox.docker_sandbox_provider import DockerSandboxProvider

    p = DockerSandboxProvider(image=_TEST_IMAGE)
    sessions: list[tuple[str, str]] = []
    yield p, sessions

    # Cleanup — destroy any sessions the test created
    for agent_id, session_id in sessions:
        try:
            p.destroy_session(agent_id, session_id)
        except Exception:
             # Best-effort teardown: ignore cleanup failures to avoid masking test outcomes.
            pass

def docker_provider():
    """DockerSandboxProvider with a fully mocked Docker client."""
    with patch(
        "agent_sandbox.docker_sandbox_provider.DockerSandboxProvider.__init__",
        return_value=None,
    ):
        provider = DockerSandboxProvider.__new__(DockerSandboxProvider)
        provider._image = "python:3.11-slim"
        provider._tools = {}
        provider._requested_runtime = IsolationRuntime.AUTO
        provider._state_lock = threading.RLock()
        provider._containers = {}
        provider._evaluators = {}
        provider._session_configs = {}
        provider._tool_proxy = None
        provider._network_proxy = None
        provider._state_manager = None
        provider._client = _make_mock_docker_client()
        provider._available = True
        provider._runtime = IsolationRuntime.RUNC

        def _create_container(agent_id, session_id, config):
