                "mktCap": 1_000_000_000,
            }

        def mock_holders(symbol):
            holders = []
            # Q4 2025: 100 genuine holders + 10 new_full + 5 exited
            for i in range(100):
                holders.append({
                    "holder": f"Fund{i}",
                    "shares": 10_000 + i * 100,
                    "change": 500 if i % 2 == 0 else -200,
                    "dateReported": "2025-12-31",
                })
            for i in range(10):
                holders.append({
                    "holder": f"NewFund{i}",
                    "shares": 5_000,
                    "change": 5_000,
                    "dateReported": "2025-12-31",
                })
            for i in range(5):
                holders.append({
                    "holder": f"ExitFund{i}",
                    "shares": 0,
                    "change": -3_000,
                    "dateReported": "2025-12-31",
