def patch_checkpointer(monkeypatch: pytest.MonkeyPatch) -> None:
    """Stub checkpointer I/O that requires real model weights or process groups."""

    def _save_checkpoint(self: object, *args: object, **kwargs: object) -> None:
        epoch = args[2] if len(args) >= 3 else kwargs.get("epoch", "0")
        self.path.joinpath(str(epoch)).mkdir(parents=True, exist_ok=True)  # type: ignore[attr-defined]

    def _noop(*_args: object, **_kwargs: object) -> None:
        return None

    for cls in (SingleGPUCheckpointer, DistributedCheckpointer):
        monkeypatch.setattr(cls, "save_checkpoint", _save_checkpoint)
        monkeypatch.setattr(cls, "save_scheduler_state_dict", _noop)
        monkeypatch.setattr(cls, "load_model_state_dict", _noop)
        monkeypatch.setattr(cls, "load_optimizer_state_dict", _noop)
        monkeypatch.setattr(cls, "load_scheduler_state_dict", _noop)

def perf_utils():
    spec = importlib.util.spec_from_file_location(
        "perf_utils", _PERF_UTILS_PATH, submodule_search_locations=[]
    )
    assert spec is not None
    assert spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    prev = sys.modules.get("perf_utils")
    sys.modules["perf_utils"] = module
    try:
        spec.loader.exec_module(module)
    except Exception:
        if prev is None:
            sys.modules.pop("perf_utils", None)
        else:
            sys.modules["perf_utils"] = prev
        raise
    return module

def tokenizer_mock():
    """Fixture to provide a mocked tokenizer."""
    tokenizer = MagicMock(spec=PreTrainedTokenizerBase)

    # Simple tokenizer: each character is a token
    def encode_side_effect(text):
        if not text:
            return []
        # Count tokens as roughly one per character for simplicity
        return list(range(len(text)))

    def decode_side_effect(tokens, skip_special_tokens=False):
        if not tokens:
            return ""
        # Simple decode: return a string representation
        return "".join(chr(65 + (t % 26)) for t in tokens[:100])

    tokenizer.encode.side_effect = encode_side_effect
    tokenizer.decode.side_effect = decode_side_effect
    return tokenizer

